'use strict';
const themes=[{id:'G',name:'Mobilitas di rumah',symbol:'↔',desc:'Jalur, pintu, dan pergerakan antarruang.',activities:['Berpindah antarruang','Membuka dan menutup pintu','Menjangkau barang']},{id:'K',name:'Dapur',symbol:'♧',desc:'Menyiapkan makanan dan menggunakan dapur.',activities:['Menyiapkan makanan','Memasak','Mencuci peralatan','Mengambil bahan makanan']},{id:'B',name:'Kamar tidur',symbol:'☾',desc:'Beristirahat, berpindah, dan merawat diri.',activities:['Berpindah ke tempat tidur','Berpakaian','Mengambil barang pribadi','Bergerak pada malam hari']},{id:'M',name:'Kamar mandi',symbol:'≈',desc:'Mandi, menggunakan toilet, dan kebersihan diri.',activities:['Menggunakan toilet','Mandi','Menggunakan wastafel','Mengambil perlengkapan mandi']}];
const profiles=[['pengisi','Siapa yang mengisi?',['Pengguna sendiri','Caregiver']],['kursi','Jenis kursi roda yang digunakan di rumah?',['Manual','Elektrik','Keduanya','Lainnya']],['bantuan','Bagaimana pengguna menggerakkan kursi roda?',['Sendiri','Kadang dibantu','Selalu dibantu']],['tangan','Tangan yang digunakan untuk mengoperasikan benda?',['Kedua tangan','Kanan','Kiri','Kedua tangan membutuhkan bantuan']],['duduk','Membutuhkan penopang tubuh saat duduk?',['Tidak','Kadang','Selalu','Belum tahu']],['transfer','Bantuan untuk berpindah dari kursi roda?',['Tanpa bantuan','Alat bantu','Bantuan orang','Bantuan orang dan alat','Belum tahu']]];
let data=[],stage=0,theme='',activity='',profile={},photos=[],answers={},qi=0;
const main=document.querySelector('main'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>themes.find(t=>t.id===theme),questions=()=>data.filter(q=>q.id.startsWith(theme+'-')),barriers=()=>questions().filter(q=>answers[q.id]===q.barrierAnswer);
const options=(values,value)=>'<option value="">Pilih jawaban</option>'+values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('');
function head(k,title,desc){return `<div class="topline"><span>LANGKAH 0${stage+1} / 05</span><span>${k}</span></div><h2>${title}</h2><p class="intro">${desc}</p>`}
function actions(next,back=true){return `<div class="actions">${back?'<button class="secondary" id="back">← Kembali</button>':'<small>Tanpa akun. Tanpa menyimpan data.</small>'}<button class="primary" id="next">${next} →</button></div>`}
function imageGrid(remove=true){return `<div class="photo-grid">${photos.map((p,i)=>`<figure><img src="${p.url}" alt="Foto ${i+1} area ${esc(current().name)}"><figcaption>Sudut ${i+1}${remove?` <button type="button" data-remove="${i}" aria-label="Hapus foto ${i+1}">Hapus ×</button>`:''}</figcaption></figure>`).join('')}</div>`}
function render(focus=true){document.querySelector('#steps').innerHTML=['Profil awal','Pilih tema','Foto ruangan','Pertanyaan','Rekomendasi'].map((s,i)=>`<div class="step ${i===stage?'current':i<stage?'done':''}" ${i===stage?'aria-current="step"':''}><span>${i<stage?'✓':i+1}</span>${s}</div>`).join('');
if(stage===0){main.innerHTML=head('MENGENAL KEBUTUHAN ANDA','Setiap orang, kebutuhan berbeda.','Ceritakan sedikit tentang pengguna kursi roda agar asesmen memiliki konteks yang tepat.')+'<div class="note">Diisi oleh caregiver? Jawablah sesuai kondisi pengguna kursi roda.</div><form id="profile"><div class="fields">'+profiles.map(([id,label,opts])=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}" required>${options(opts,profile[id])}</select></div>`).join('')+'</div>'+actions('Pilih area rumah',false)+'</form>';document.querySelector('#profile').onsubmit=e=>{e.preventDefault();profile=Object.fromEntries(new FormData(e.target));stage=1;render()};}
if(stage===1){main.innerHTML=head('SATU AREA DALAM SATU ASESMEN','Mulai dari area yang penting.','Pilih area yang ingin diperiksa terlebih dahulu. Anda hanya akan menjawab pertanyaan untuk area ini.')+`<div class="themes">${themes.map(t=>`<button class="theme ${theme===t.id?'selected':''}" data-theme="${t.id}" aria-pressed="${theme===t.id}"><span class="symbol" aria-hidden="true">${t.symbol}</span><strong>${t.name}</strong><p>${t.desc}</p><small>${data.filter(q=>q.id.startsWith(t.id+'-')).length} PERTANYAAN</small></button>`).join('')}</div>`+(theme?`<div class="field" style="margin-top:25px"><label for="activity">Aktivitas apa yang paling ingin dipermudah?</label><select id="activity">${options(current().activities,activity)}</select><small>Pilih satu aktivitas prioritas.</small></div>`:'')+actions('Tambahkan foto');document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{if(theme!==b.dataset.theme){theme=b.dataset.theme;activity='';answers={};qi=0;photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[]}render(false)});if(theme)document.querySelector('#activity').onchange=e=>{activity=e.target.value;document.querySelector('#next').disabled=!activity};document.querySelector('#next').disabled=!theme||!activity;document.querySelector('#next').onclick=()=>{stage=2;render()};document.querySelector('#back').onclick=()=>{stage=0;render()};}
if(stage===2){main.innerHTML=head(current().name,'Lihat ruang dari beberapa sudut.','Tambahkan foto area secara keseluruhan, jalur masuk, dan bagian yang terasa sulit digunakan.')+'<div class="note">Ambil 1–6 foto yang cukup terang. Hindari wajah dan informasi pribadi. Foto hanya ditampilkan sebagai konteks; tidak dianalisis oleh AI.</div><div class="upload"><span style="font-size:35px" aria-hidden="true">⊞</span><h3>Tambahkan foto ruangan</h3><p>JPG, PNG, atau WebP · maksimal 10 MB per foto</p><div class="photo-options"><button type="button" class="primary" id="upload-device">Unggah foto dari perangkat</button><button type="button" class="secondary" id="take-photo">Ambil foto dengan kamera</button></div><p class="upload-hint">Pilih foto yang sudah ada di galeri atau folder perangkat Anda.</p><input id="files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden aria-label="Pilih foto dari perangkat"><input id="camera" type="file" accept="image/*" capture="environment" hidden aria-label="Ambil foto dengan kamera"></div><p id="photo-error" class="error" role="status"></p>'+imageGrid()+actions('Mulai pertanyaan');const add=async e=>{const errors=[];for(const file of e.target.files){if(photos.length>=6){errors.push('Maksimal 6 foto.');break}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){errors.push('Gunakan JPG, PNG, atau WebP dengan ukuran maksimal 10 MB.');continue}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();photos.push({url})}catch{URL.revokeObjectURL(url);errors.push('Foto tidak dapat dibaca. Pilih foto lain.')}}render(false);document.querySelector('#photo-error').textContent=errors.join(' ')};document.querySelector('#upload-device').onclick=()=>document.querySelector('#files').click();document.querySelector('#take-photo').onclick=()=>document.querySelector('#camera').click();document.querySelector('#files').onchange=add;document.querySelector('#camera').onchange=add;document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{URL.revokeObjectURL(photos[+b.dataset.remove].url);photos.splice(+b.dataset.remove,1);render(false)});document.querySelector('#next').disabled=!photos.length;document.querySelector('#next').onclick=()=>{stage=3;render()};document.querySelector('#back').onclick=()=>{stage=1;render()};}
if(stage===3){const qs=questions(),q=qs[qi];main.innerHTML=head(current().name,'Periksa satu hal, selangkah demi selangkah.','Jawab sesuai kondisi ruangan saat ini. Buka panduan pemeriksaan jika diperlukan.')+`<div class="topline"><span>PERTANYAAN ${qi+1} DARI ${qs.length}</span><span>${qs.filter(x=>answers[x.id]).length} terjawab</span></div><div class="progress" role="progressbar" aria-label="Pertanyaan terjawab" aria-valuemin="0" aria-valuemax="${qs.length}" aria-valuenow="${qs.filter(x=>answers[x.id]).length}"><div style="width:${100*qs.filter(x=>answers[x.id]).length/qs.length}%"></div></div><section class="question-box"><span class="eyebrow">${q.id} · ${esc(q.label)}</span><h3 id="question">${esc(q.question)}</h3><div class="answers" role="group" aria-labelledby="question">${['Ya','Tidak'].map(a=>`<button class="answer ${answers[q.id]===a?'active':''}" data-answer="${a}" aria-pressed="${answers[q.id]===a}">${a}</button>`).join('')}</div></section><details open><summary>Cara memeriksa</summary><p>${esc(q.verify)}</p><strong>Kondisi yang diharapkan</strong><p>${esc(q.ideal)}</p><details><summary>Referensi indikator</summary><p>${esc(q.source)}</p></details></details>`+actions(qi===qs.length-1?'Lihat rekomendasi':'Pertanyaan berikutnya');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[q.id]=b.dataset.answer;document.querySelectorAll('[data-answer]').forEach(x=>{x.classList.toggle('active',x.dataset.answer===answers[q.id]);x.setAttribute('aria-pressed',String(x.dataset.answer===answers[q.id]))});document.querySelector('#next').disabled=false});document.querySelector('#next').disabled=!answers[q.id];document.querySelector('#next').onclick=()=>{if(qi<qs.length-1)qi++;else if(qs.every(x=>answers[x.id]))stage=4;render()};document.querySelector('#back').onclick=()=>{if(qi>0)qi--;else stage=2;render()};}
if(stage===4){const qs=questions(),bad=barriers();main.innerHTML=head(current().name,'Ruang yang lebih mendukung Anda.',`Prioritas Anda: ${esc(activity.toLowerCase())}. Berikut hasil berdasarkan jawaban asesmen.`)+`<div class="results-summary"><div class="big-number">${bad.length}<span style="font-size:22px">/${qs.length}</span></div><div><p><strong>aspek membutuhkan penyesuaian</strong></p><small>${qs.length-bad.length} aspek tidak menunjukkan hambatan berdasarkan jawaban Anda.</small></div></div><details><summary>Profil dan foto ruangan</summary><p>${profiles.map(([id,label])=>`${esc(label)} ${esc(profile[id])}`).join('<br>')}</p>${imageGrid(false)}</details><div class="note">Ilustrasi modifikasi ruangan dengan AI belum tersedia dalam versi ini. Foto Anda tetap menjadi referensi visual asli.</div>`+(bad.length?bad.map((q,i)=>`<article class="rec"><div class="rec-head"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(q.label)}</h3></div><span class="badge">${q.id} · Jawaban: ${answers[q.id]}</span><p>${esc(q.question)}</p><div class="rec-columns"><div><h4>PENYESUAIAN PRAKTIS</h4><p>${esc(q.hack)}</p></div><div><h4>PILIHAN MODIFIKASI</h4><p>${esc(q.modification)}</p></div></div><details><summary>Acuan & cara memeriksa kembali</summary><p>${esc(q.verify)}</p><p>${esc(q.ideal)}</p><p>${esc(q.references)}</p></details></article>`).join(''):'<div class="empty"><h3>Tidak ada hambatan yang teridentifikasi.</h3><p>Semua jawaban pada tema ini memenuhi indikator asesmen. Hasil ini menggambarkan jawaban Anda, bukan sertifikasi keselamatan rumah.</p></div>')+`<details class="no-print"><summary>Tinjau semua jawaban (${qs.length})</summary>${qs.map((q,i)=>`<div class="review-row"><span>${esc(q.question)} <strong>${answers[q.id]}</strong></span><button class="text-button" data-edit="${i}">Ubah</button></div>`).join('')}</details><p style="font-size:12px;color:var(--muted)">Sumber: Checklist Physical Accesibility Audit — Pertanyaan Assesmen. Rekomendasi mengikuti dokumen sumber; perubahan struktur, listrik, atau pemasangan penopang memerlukan pemeriksaan tenaga yang kompeten.</p><div class="actions"><button class="secondary" id="print">Cetak / simpan PDF</button><button class="primary" id="another">Periksa area lain →</button></div>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{qi=+b.dataset.edit;stage=3;render()});document.querySelector('#print').onclick=()=>window.print();document.querySelector('#another').onclick=()=>{photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];answers={};qi=0;theme='';activity='';stage=1;render()};}
if(focus){main.focus();window.scrollTo(0,0)}}
document.querySelector('#reset').onclick=()=>{if(confirm('Mulai ulang? Semua jawaban dan foto di tab ini akan dihapus.')){photos.forEach(p=>URL.revokeObjectURL(p.url));photos=[];profile={};answers={};theme='';activity='';qi=0;stage=0;render()}};
fetch('questions.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(rows=>{data=rows;render(false)}).catch(()=>{main.innerHTML='<h2>Pertanyaan belum dapat dimuat.</h2><p>Pastikan server lokal berjalan, lalu muat ulang halaman.</p>'});
